-- +goose StatementBegin
DO $$
DECLARE
    v_missing_paths text;
    v_dup_groups integer;
    v_dup_commands integer;
BEGIN
    IF (SELECT COUNT(*) FROM tmp_mml_350_sub_fields) <> 350 THEN
        RAISE EXCEPTION 'expected 350 document rows, got %', (SELECT COUNT(*) FROM tmp_mml_350_sub_fields);
    END IF;
    IF (SELECT COUNT(DISTINCT standard_path) FROM tmp_mml_350_sub_fields) <> 350 THEN
        RAISE EXCEPTION 'expected 350 distinct standard_path rows, got %', (SELECT COUNT(DISTINCT standard_path) FROM tmp_mml_350_sub_fields);
    END IF;
    IF (SELECT COUNT(*) FROM tmp_mml_350_groups) <> 15 THEN
        RAISE EXCEPTION 'expected 15 group rows, got %', (SELECT COUNT(*) FROM tmp_mml_350_groups);
    END IF;
    IF (SELECT COUNT(*) FROM tmp_mml_350_commands) <> 54 THEN
        RAISE EXCEPTION 'expected 54 command rows, got %', (SELECT COUNT(*) FROM tmp_mml_350_commands);
    END IF;

    SELECT COUNT(*) - COUNT(DISTINCT group_code) INTO v_dup_groups FROM tmp_mml_350_groups;
    IF v_dup_groups <> 0 THEN
        RAISE EXCEPTION 'duplicate tmp group_code count: %', v_dup_groups;
    END IF;

    SELECT COUNT(*) - COUNT(DISTINCT command_code) INTO v_dup_commands FROM tmp_mml_350_commands;
    IF v_dup_commands <> 0 THEN
        RAISE EXCEPTION 'duplicate tmp command_code count: %', v_dup_commands;
    END IF;

    SELECT string_agg(s.standard_path, E'
' ORDER BY s.standard_path)
      INTO v_missing_paths
    FROM tmp_mml_350_sub_fields s
    LEFT JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
    WHERE sp.id IS NULL;
    IF v_missing_paths IS NOT NULL THEN
        RAISE EXCEPTION 'standard_params missing paths:%', E'
' || v_missing_paths;
    END IF;
END $$;
-- +goose StatementEnd

WITH ordered_groups AS (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.display_order, t.group_code) AS append_offset
    FROM tmp_mml_350_groups t
), append_base AS (
    SELECT COALESCE(MAX(g.display_order), 0) AS max_display_order
    FROM public.mml_command_groups g
    WHERE g.param_version = 'cmcc-td-lte-v2.3'
      AND g.deleted_at IS NULL
      AND g.deprecated_at IS NULL
      AND g.is_active = true
      AND g.group_code <> 'MML350_20260704'
      AND NOT EXISTS (
          SELECT 1 FROM tmp_mml_350_groups t
          WHERE t.param_version = g.param_version AND t.group_code = g.group_code
      )
)
UPDATE public.mml_command_groups g
SET group_name_zh     = og.group_name_zh,
    group_name_en     = og.group_name_en,
    path              = og.path_text::ltree,
    display_order     = ab.max_display_order + og.append_offset,
    name_i18n         = og.name_i18n,
    source            = og.source,
    catalog_protected = og.catalog_protected,
    chapter_code      = NULLIF(og.chapter_code, ''),
    is_active         = true,
    deleted_at        = NULL,
    deprecated_at     = NULL,
    updated_at        = NOW()
FROM ordered_groups og, append_base ab
WHERE g.param_version = og.param_version
  AND g.group_code = og.group_code;

WITH ordered_groups AS (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.display_order, t.group_code) AS append_offset
    FROM tmp_mml_350_groups t
), append_base AS (
    SELECT COALESCE(MAX(g.display_order), 0) AS max_display_order
    FROM public.mml_command_groups g
    WHERE g.param_version = 'cmcc-td-lte-v2.3'
      AND g.deleted_at IS NULL
      AND g.deprecated_at IS NULL
      AND g.is_active = true
      AND g.group_code <> 'MML350_20260704'
      AND NOT EXISTS (
          SELECT 1 FROM tmp_mml_350_groups t
          WHERE t.param_version = g.param_version AND t.group_code = g.group_code
      )
)
INSERT INTO public.mml_command_groups (
    id, group_code, group_name_zh, group_name_en, path, param_version,
    display_order, name_i18n, source, catalog_protected, chapter_code
)
SELECT
    gen_random_uuid(), og.group_code, og.group_name_zh, og.group_name_en,
    og.path_text::ltree, og.param_version, ab.max_display_order + og.append_offset,
    og.name_i18n, og.source, og.catalog_protected, NULLIF(og.chapter_code, '')
FROM ordered_groups og
CROSS JOIN append_base ab
WHERE NOT EXISTS (
    SELECT 1 FROM public.mml_command_groups existing
    WHERE existing.param_version = og.param_version AND existing.group_code = og.group_code
);

-- +goose StatementBegin
DO $$
DECLARE
    v_duplicate_existing_groups text;
    v_missing_groups text;
BEGIN
    SELECT string_agg(group_code || ' count=' || cnt, E'
' ORDER BY group_code)
      INTO v_duplicate_existing_groups
    FROM (
        SELECT g.group_code, COUNT(*) AS cnt
        FROM public.mml_command_groups g
        JOIN tmp_mml_350_groups t ON t.param_version = g.param_version AND t.group_code = g.group_code
        GROUP BY g.group_code
        HAVING COUNT(*) > 1
    ) d;
    IF v_duplicate_existing_groups IS NOT NULL THEN
        RAISE EXCEPTION 'duplicate existing mml_command_groups for this import:%', E'
' || v_duplicate_existing_groups;
    END IF;

    SELECT string_agg(c.group_code, ', ' ORDER BY c.group_code)
      INTO v_missing_groups
    FROM (SELECT DISTINCT group_code FROM tmp_mml_350_commands) c
    LEFT JOIN public.mml_command_groups g
      ON g.param_version = 'cmcc-td-lte-v2.3'
     AND g.group_code = c.group_code
     AND g.deleted_at IS NULL
     AND g.deprecated_at IS NULL
    WHERE g.id IS NULL;
    IF v_missing_groups IS NOT NULL THEN
        RAISE EXCEPTION 'missing mml_command_groups for command rows: %', v_missing_groups;
    END IF;
END $$;
-- +goose StatementEnd

INSERT INTO public.mml_commands (
    id, command_name, command_code, category, description, rpc_method,
    operation_type, target_paths, group_id, command_name_i18n,
    require_confirm, confirm_msg_i18n, logical_name_i18n,
    source, catalog_protected
)
SELECT
    gen_random_uuid(), c.command_name_zh, c.command_code, c.category, c.description,
    c.rpc_method, c.operation_type, c.target_paths, g.id,
    jsonb_build_object('zh-CN', c.command_name_zh, 'en-US', c.command_name_en),
    false, '{}'::jsonb,
    jsonb_build_object('zh-CN', c.logical_name_zh, 'en-US', c.logical_name_en),
    'admin', false
FROM tmp_mml_350_commands c
JOIN public.mml_command_groups g
  ON g.param_version = 'cmcc-td-lte-v2.3'
 AND g.group_code = c.group_code
 AND g.deleted_at IS NULL
 AND g.deprecated_at IS NULL
ON CONFLICT (command_code) DO UPDATE
SET command_name      = EXCLUDED.command_name,
    category          = EXCLUDED.category,
    description       = EXCLUDED.description,
    rpc_method        = EXCLUDED.rpc_method,
    operation_type    = EXCLUDED.operation_type,
    target_paths      = EXCLUDED.target_paths,
    group_id          = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    require_confirm   = EXCLUDED.require_confirm,
    confirm_msg_i18n  = EXCLUDED.confirm_msg_i18n,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source            = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    deprecated_at     = NULL,
    updated_at        = NOW();

-- +goose StatementBegin
DO $$
DECLARE
    v_missing_commands text;
    v_dup_final_code integer;
    v_existing_code_conflict text;
BEGIN
    SELECT string_agg(s.command_code, ', ' ORDER BY s.command_code)
      INTO v_missing_commands
    FROM (
        SELECT DISTINCT s.command_code
        FROM tmp_mml_350_sub_fields s
        LEFT JOIN public.mml_commands c ON c.command_code = s.command_code AND c.deprecated_at IS NULL
        WHERE c.id IS NULL
    ) s;
    IF v_missing_commands IS NOT NULL THEN
        RAISE EXCEPTION 'missing mml_commands after upsert: %', v_missing_commands;
    END IF;

    WITH resolved AS (
        SELECT s.*, c.id AS command_id, sp.id AS standard_path_id
        FROM tmp_mml_350_sub_fields s
        JOIN public.mml_commands c ON c.command_code = s.command_code AND c.deprecated_at IS NULL
        JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
    ), normalized AS (
        SELECT r.*, COALESCE(NULLIF(LEFT(r.base_mml_code, 100), ''), 'PATH_' || substr(md5(r.standard_path), 1, 8)) AS base_code
        FROM resolved r
    ), prepared AS (
        SELECT n.*,
               CASE
                   WHEN COUNT(*) OVER (PARTITION BY n.command_id, n.base_code) > 1
                     OR EXISTS (
                         SELECT 1 FROM public.mml_command_sub_fields e
                         WHERE e.command_id = n.command_id
                           AND e.mml_code = n.base_code
                           AND e.standard_path_id <> n.standard_path_id
                     )
                   THEN LEFT(n.base_code, 91) || '_' || substr(md5(n.standard_path), 1, 8)
                   ELSE n.base_code
               END AS final_mml_code
        FROM normalized n
    )
    SELECT COUNT(*) - COUNT(DISTINCT (command_id, final_mml_code)) INTO v_dup_final_code FROM prepared;
    IF v_dup_final_code <> 0 THEN
        RAISE EXCEPTION 'generated duplicate final mml_code count: %', v_dup_final_code;
    END IF;

    WITH resolved AS (
        SELECT s.*, c.id AS command_id, sp.id AS standard_path_id
        FROM tmp_mml_350_sub_fields s
        JOIN public.mml_commands c ON c.command_code = s.command_code AND c.deprecated_at IS NULL
        JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
    ), normalized AS (
        SELECT r.*, COALESCE(NULLIF(LEFT(r.base_mml_code, 100), ''), 'PATH_' || substr(md5(r.standard_path), 1, 8)) AS base_code
        FROM resolved r
    ), prepared AS (
        SELECT n.*,
               CASE
                   WHEN COUNT(*) OVER (PARTITION BY n.command_id, n.base_code) > 1
                     OR EXISTS (
                         SELECT 1 FROM public.mml_command_sub_fields e
                         WHERE e.command_id = n.command_id
                           AND e.mml_code = n.base_code
                           AND e.standard_path_id <> n.standard_path_id
                     )
                   THEN LEFT(n.base_code, 91) || '_' || substr(md5(n.standard_path), 1, 8)
                   ELSE n.base_code
               END AS final_mml_code
        FROM normalized n
    )
    SELECT string_agg(p.command_code || ' / ' || p.standard_path || ' -> ' || p.final_mml_code, E'
' ORDER BY p.command_code, p.standard_path)
      INTO v_existing_code_conflict
    FROM prepared p
    JOIN public.mml_command_sub_fields e
      ON e.command_id = p.command_id
     AND e.mml_code = p.final_mml_code
     AND e.standard_path_id <> p.standard_path_id;
    IF v_existing_code_conflict IS NOT NULL THEN
        RAISE EXCEPTION 'mml_code conflicts with existing sub_fields:%', E'
' || v_existing_code_conflict;
    END IF;
END $$;
-- +goose StatementEnd

WITH resolved AS (
    SELECT s.*, c.id AS command_id, sp.id AS standard_path_id
    FROM tmp_mml_350_sub_fields s
    JOIN public.mml_commands c ON c.command_code = s.command_code AND c.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
), normalized AS (
    SELECT r.*, COALESCE(NULLIF(LEFT(r.base_mml_code, 100), ''), 'PATH_' || substr(md5(r.standard_path), 1, 8)) AS base_code
    FROM resolved r
), prepared AS (
    SELECT n.*,
           CASE
               WHEN COUNT(*) OVER (PARTITION BY n.command_id, n.base_code) > 1
                 OR EXISTS (
                     SELECT 1 FROM public.mml_command_sub_fields e
                     WHERE e.command_id = n.command_id
                       AND e.mml_code = n.base_code
                       AND e.standard_path_id <> n.standard_path_id
                 )
               THEN LEFT(n.base_code, 91) || '_' || substr(md5(n.standard_path), 1, 8)
               ELSE n.base_code
           END AS final_mml_code
    FROM normalized n
)
INSERT INTO public.mml_command_sub_fields (
    id, command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type
)
SELECT gen_random_uuid(), p.command_id, p.final_mml_code, p.label_i18n,
       p.default_selected, p.is_required, p.input_order, p.standard_path_id, p.access_type
FROM prepared p
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code         = EXCLUDED.mml_code,
    label_i18n       = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required      = EXCLUDED.is_required,
    sort_order       = EXCLUDED.sort_order,
    access_type      = EXCLUDED.access_type,
    deprecated_at    = NULL,
    updated_at       = NOW();

DELETE FROM public.mml_command_groups old_root
WHERE old_root.param_version = 'cmcc-td-lte-v2.3'
  AND old_root.group_code = 'MML350_20260704'
  AND old_root.source = 'admin'
  AND NOT EXISTS (
      SELECT 1 FROM public.mml_commands c
      WHERE c.group_id = old_root.id AND c.deprecated_at IS NULL
  )
  AND NOT EXISTS (
      SELECT 1 FROM public.mml_command_groups child
      WHERE child.id <> old_root.id
        AND child.path <@ old_root.path
        AND child.deleted_at IS NULL
        AND child.deprecated_at IS NULL
  );

-- +goose StatementBegin
DO $$
DECLARE
    v_actual_bindings integer;
    v_actual_groups integer;
    v_actual_commands integer;
    v_old_root integer;
BEGIN
    SELECT COUNT(*) INTO v_actual_groups
    FROM tmp_mml_350_groups t
    JOIN public.mml_command_groups g ON g.param_version = t.param_version AND g.group_code = t.group_code AND g.deleted_at IS NULL AND g.deprecated_at IS NULL;
    IF v_actual_groups <> 15 THEN
        RAISE EXCEPTION 'expected 15 imported groups, got %', v_actual_groups;
    END IF;

    SELECT COUNT(*) INTO v_actual_commands
    FROM tmp_mml_350_commands t
    JOIN public.mml_commands c ON c.command_code = t.command_code AND c.deprecated_at IS NULL;
    IF v_actual_commands <> 54 THEN
        RAISE EXCEPTION 'expected 54 imported commands, got %', v_actual_commands;
    END IF;

    SELECT COUNT(*) INTO v_actual_bindings
    FROM tmp_mml_350_sub_fields s
    JOIN public.mml_commands c ON c.command_code = s.command_code AND c.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
    JOIN public.mml_command_sub_fields csf ON csf.command_id = c.id AND csf.standard_path_id = sp.id AND csf.deprecated_at IS NULL;
    IF v_actual_bindings <> 350 THEN
        RAISE EXCEPTION 'expected 350 command-path bindings, got %', v_actual_bindings;
    END IF;

    SELECT COUNT(*) INTO v_old_root
    FROM public.mml_command_groups g
    WHERE g.param_version = 'cmcc-td-lte-v2.3'
      AND g.group_code = 'MML350_20260704'
      AND g.deleted_at IS NULL
      AND g.deprecated_at IS NULL;
    IF v_old_root <> 0 THEN
        RAISE EXCEPTION 'old supplemental root % still exists', 'MML350_20260704';
    END IF;
END $$;
-- +goose StatementEnd

