WITH target AS (
    SELECT csf.id
    FROM tmp_mml_350_sub_fields s
    JOIN public.mml_commands c ON c.command_code = s.command_code
    JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
    JOIN public.mml_command_sub_fields csf ON csf.command_id = c.id AND csf.standard_path_id = sp.id
), deleted AS (
    DELETE FROM public.mml_command_sub_fields csf
    USING target t
    WHERE csf.id = t.id
    RETURNING csf.id
)
SELECT 'deleted_sub_fields' AS action, COUNT(*) AS rows FROM deleted;

WITH deleted AS (
    DELETE FROM public.mml_commands c
    USING tmp_mml_350_commands t
    WHERE c.command_code = t.command_code
      AND c.source = 'admin'
      AND NOT EXISTS (SELECT 1 FROM public.mml_command_sub_fields csf WHERE csf.command_id = c.id)
    RETURNING c.id
)
SELECT 'deleted_commands' AS action, COUNT(*) AS rows FROM deleted;

WITH deleted AS (
    DELETE FROM public.mml_command_groups g
    USING tmp_mml_350_groups t
    WHERE g.param_version = t.param_version
      AND g.group_code = t.group_code
      AND g.source = 'admin'
      AND NOT EXISTS (SELECT 1 FROM public.mml_commands c WHERE c.group_id = g.id AND c.deprecated_at IS NULL)
      AND NOT EXISTS (
          SELECT 1 FROM public.mml_command_groups child
          WHERE child.id <> g.id
            AND child.path <@ g.path
            AND child.deleted_at IS NULL
            AND child.deprecated_at IS NULL
      )
    RETURNING g.id
)
SELECT 'deleted_groups' AS action, COUNT(*) AS rows FROM deleted;

SELECT 'remaining_sub_fields' AS metric, COUNT(*) AS rows
FROM tmp_mml_350_sub_fields s
JOIN public.mml_commands c ON c.command_code = s.command_code
JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
JOIN public.mml_command_sub_fields csf ON csf.command_id = c.id AND csf.standard_path_id = sp.id
UNION ALL
SELECT 'remaining_commands', COUNT(*)
FROM tmp_mml_350_commands t
JOIN public.mml_commands c ON c.command_code = t.command_code
UNION ALL
SELECT 'remaining_groups', COUNT(*)
FROM tmp_mml_350_groups t
JOIN public.mml_command_groups g ON g.param_version = t.param_version AND g.group_code = t.group_code
UNION ALL
SELECT 'remaining_old_root', COUNT(*)
FROM public.mml_command_groups g
WHERE g.param_version = 'cmcc-td-lte-v2.3' AND g.group_code = 'MML350_20260704' AND g.deleted_at IS NULL AND g.deprecated_at IS NULL;
